    fun readBorderStroke(value: JsonElement): BorderStrokeValue {
        ValueParser.validate(value, "BorderStroke", specs).getOrThrow()
        val data = value.jsonObject
        return when (data.getValue("type").jsonPrimitive.content) {
            "BorderStroke" -> WireBorderStroke(
                supplied = data.keys,
                width = readDp(data.getValue("width")),
                brush = readBrush(data.getValue("brush")),
            )
            else -> error("Unknown value constructor")
        }
    }

    fun readBrush(value: JsonElement): BrushValue {
        ValueParser.validate(value, "Brush", specs).getOrThrow()
        val data = value.jsonObject
        return when (data.getValue("type").jsonPrimitive.content) {
            "SolidColor" -> WireSolidColor(
                supplied = data.keys,
                value = readColor(data.getValue("value")),
            )
            "horizontalGradient" -> WirehorizontalGradient(
                supplied = data.keys,
                colors = (data.getValue("colors") as JsonArray).map { element -> readColor(element) },
                startX = data["startX"]?.takeUnless { it == JsonNull }?.let { item -> item.jsonPrimitive.double },
                endX = data["endX"]?.takeUnless { it == JsonNull }?.let { item -> item.jsonPrimitive.double },
            )
            "linearGradient" -> WirelinearGradient(
                supplied = data.keys,
                colors = (data.getValue("colors") as JsonArray).map { element -> readColor(element) },
                start = data["start"]?.takeUnless { it == JsonNull }?.let { item -> readOffset(item) },
                end = data["end"]?.takeUnless { it == JsonNull }?.let { item -> readOffset(item) },
            )
            "verticalGradient" -> WireverticalGradient(
                supplied = data.keys,
                colors = (data.getValue("colors") as JsonArray).map { element -> readColor(element) },
                startY = data["startY"]?.takeUnless { it == JsonNull }?.let { item -> item.jsonPrimitive.double },
                endY = data["endY"]?.takeUnless { it == JsonNull }?.let { item -> item.jsonPrimitive.double },
            )
            else -> error("Unknown value constructor")
        }
    }

